59	/**
60	 * @brief 初始化 lv_pm、注册页面、套默认主题与状态栏。
61	 */
62	void lvgl_page_init(void)
63	{
64	    if (lv_pm_init((int)BICYCLE_PM_ID_COUNT) != 0) {
65	        LV_LOG_ERROR("lvgl_page: lv_pm_init failed");
66	        return;
67	    }
68	
69	    bicycle_runtime_ui_init();
70	    lv_pm_set_nav_notify_cb(lvgl_page_on_nav, NULL);
71	
72	    lv_obj_set_style_bg_color(lv_scr_act(), lv_color_black(), LV_PART_MAIN);
73	
74	    if (myvendor_is_factory()) {
75	#ifdef CONFIG_MYVENDOR_FACTORY_MODE
76	        factory_page_register();
77	        LV_LOG_INFO("lvgl_page: factory page (no TTF / LiveMap)");
78	        return;
79	#else
80	        LV_LOG_ERROR("lvgl_page: factory image missing CONFIG_MYVENDOR_FACTORY_MODE");
81	        return;
82	#endif
83	    }
84	
85	    live_map_page_register();
86	    usb_transfer_page_register();
87	    startup_page_register();
88	    helm_menu_page_register();
89	
90	    lv_pm_theme_set(0);
91	    /* 把 helm 调色板挂到 lv_pm 的主题框架上：主题一变就换表 + 整屏失效。 */
92	    helm_palette_follow_theme_hook();
93	    lv_pm_i18n_set(LV_PM_I18N_DEFAULT_LOCALE);
94	    lv_pm_status_bar_set_height(VMAP_STATUSBAR_H);
95	    bicycle_status_bar_init();
96	
97	    LV_LOG_INFO("lvgl_page: pages registered");
98	}
