488	{
489	    if (obj == NULL) {
490	        return;
491	    }
492	
493	    if (on) {
494	        if (lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
495	            lv_obj_clear_flag(obj, LV_OBJ_FLAG_HIDDEN);
496	            lv_obj_move_foreground(obj);
497	        }
498	    } else if (!lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
499	        lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);

600	    }
601	
602	    if (animate && !helm_anim_is_suspended()) {
603	        int32_t cur;
604	
605	        if (s_nav_ban_hiding) {
606	            return;  /* 已经在下滑：不要从 0 再启动一次，否则屏上会跳一下 */
607	        }
608	        s_nav_ban_hiding = true;
609	        /* 从当前偏移接着滑（入场还没走完就结束导航时不要先跳回 0）。 */
610	        cur = lv_obj_get_style_translate_y(s_sh.nav_ban, 0);
611	        helm_anim_run(s_sh.nav_ban, helm_nav_ban_y_exec, cur, -8, 140,
612	                      lv_anim_path_ease_in, helm_nav_ban_y_done);
613	    } else {
614	        /* 切页/挂起：立即收起，不留半截动画。 */
615	        helm_anim_stop(s_sh.nav_ban, helm_nav_ban_y_exec);
616	        s_nav_ban_hiding = false;
617	        lv_obj_add_flag(s_sh.nav_ban, LV_OBJ_FLAG_HIDDEN);
618	        lv_obj_set_style_translate_y(s_sh.nav_ban, 0, 0);
619	    }
620	}
