4019	static uint32_t helm_gps_label(const bicycle_runtime_t * rt, char * buf, size_t n)
4020	{
4021	    uint8_t sats = rt ? rt->gnss_satellites : 0;
4022	    uint8_t q = rt ? rt->gnss_fix_quality : 0;
4023	    uint8_t h = rt ? rt->gnss_hdop_x10 : 0;
4024	    bool valid = rt && rt->gnss_valid;
4025	    bool alive = rt && rt->gnss_alive;
4026	    bool eph = rt && rt->gnss_eph_busy;
4027	    const char * conf = NULL;
4028	
4029	    if (eph) {
4030	        lv_snprintf(buf, n, "星历同步");
4031	        return HELM_COLOR_WARN;
4032	    }
4033	
4034	    if (!valid) {
4035	        if (!alive) {
4036	            if (helm_idle_is_sleeping()) {
4037	                lv_snprintf(buf, n, "无定位");
4038	                return HELM_COLOR_INK;
4039	            }
4040	
4041	            lv_snprintf(buf, n, "无数据");
4042	            return HELM_COLOR_GPS_DEAD;
4043	        }
4044	
4045	        if (sats == 0) {
4046	            lv_snprintf(buf, n, "无定位");
4047	            return HELM_COLOR_INK;
4048	        }
4049	
4050	        lv_snprintf(buf, n, "搜索 %u", (unsigned)sats);
4051	        return HELM_COLOR_WARN;
4052	    }
4053	
4054	    if (h > 0) {
4055	        if (h <= 10) {
4056	            conf = "高";
4057	        } else if (h <= 20) {
4058	            conf = "中";
4059	        } else {
4060	            conf = "低";
4061	        }
4062	    }
4063	
4064	    if (q <= 1) {
4065	        if (conf != NULL) {
4066	            lv_snprintf(buf, n, "2D %s", conf);
4067	        } else {
4068	            lv_snprintf(buf, n, "2D定位");
4069	        }
4070	
4071	        return (h > 0 && h <= 20) ? HELM_COLOR_INK : HELM_COLOR_WARN;
4072	    }
4073	
4074	    if (conf != NULL) {
4075	        lv_snprintf(buf, n, "3D %s", conf);
4076	    } else {
4077	        lv_snprintf(buf, n, "3D定位");
4078	    }
4079	
4080	    return (h > 20) ? HELM_COLOR_INK : HELM_COLOR_CAD;
4081	}
