8176	    if (root == NULL) {
8177	        return;
8178	    }
8179	
8180	    /* ⚠ 临时诊断（换主题卡死定位，定位完删）：每步一条，卡住的**最后一条**就是现场。 */
8181	    syslog(LOG_WARNING, "[theme] attach enter children=%u keep_n=%u",
8182	           (unsigned)lv_obj_get_child_count(root), (unsigned)s_build_keep_n);
8183	
8184	    /* attach 之前 root 已有的子对象数 = 外来件（地图画布等）的个数，重建时要留着；
8185	     * 本层建完（见下面 build 之后那段）再把**新增**的子对象打上 LV_OBJ_FLAG_USER_2，
8186	     * helm_shell_rebuild() 只删这些。 */
8187	    s_build_keep_n = (uint8_t)lv_obj_get_child_count(root);
8188	
8189	    /* ⚠ 走势图登记表（`s_spark[]`）**必须跟着本层的对象一起重建**：表里存的是本层
8190	     * chart/label/series 的指针，而每次 attach 都会把这些对象删掉重造。
8191	     * 2026-09-26 现场（coredump n623）：表**只增不清** ⇒ 重建后表里留着**已释放**的
8192	     * 指针，主界面左右翻页走 `helm_spark_sync()` 时 `lv_obj_has_flag(野指针)`
8193	     * 直接内存故障重启（判据：pc=`lv_obj_has_flag`、lr=`helm_spark_tree_shown`、
8194	     * 故障地址 0x07e90024 是野值）。放在 builders **之前**：delete 回调会先把旧表项
8195	     * 置 NULL，这里再整表清零，随后 builders 按新对象重新登记。 */
8196	    memset(s_spark, 0, sizeof(s_spark));
8197	    s_spark_n = 0;
8198	
8199	    s_sh.map = map;
8200	    s_sh.font_lab = helm_font_lab();
8201	    s_sh.font_title = helm_font_title();
8202	    s_sh.font_val = helm_font_val();
8203	    s_sh.font_quad = helm_font_quad();
8204	    s_sh.font_rot = helm_font_rot_speed();
8205	    s_sh.font_speed = helm_font_speed();
8206	    s_sh.font_speed_ride = helm_font_speed_ride();
8207	    s_sh.font_mark = helm_font_mark();
8208	
8209	    syslog(LOG_WARNING, "[theme] chrome");
8210	    helm_build_chrome(root);
8211	    syslog(LOG_WARNING, "[theme] standby");
8212	    helm_build_standby(root);
8213	    syslog(LOG_WARNING, "[theme] data");
8214	    helm_build_data(root);
8215	    syslog(LOG_WARNING, "[theme] data_all");
8216	    helm_build_data_all(root);
8217	    syslog(LOG_WARNING, "[theme] turn");
8218	    helm_build_turn(root);
8219	    syslog(LOG_WARNING, "[theme] climb");
8220	    helm_build_climb(root);
8221	    syslog(LOG_WARNING, "[theme] pause");
8222	    helm_build_pause(root);
8223	    syslog(LOG_WARNING, "[theme] save");
8224	    helm_build_save(root);
8225	    syslog(LOG_WARNING, "[theme] arrive");
8226	    helm_build_arrive(root);
8227	    syslog(LOG_WARNING, "[theme] hist_reset");
8228	    helm_hist_reset();
8229	    syslog(LOG_WARNING, "[theme] flag");
8230	
8231	    /* 本层新建的子对象打标记 ⇒ helm_shell_rebuild() 重建时只删它们。 */    {
8232	        uint32_t n = lv_obj_get_child_count(root);
8233	        uint32_t k;
8234	
8235	        for (k = s_build_keep_n; k < n; k++) {
8236	            lv_obj_t * c = lv_obj_get_child(root, k);
8237	
8238	            if (c != NULL) {
8239	                lv_obj_add_flag(c, LV_OBJ_FLAG_USER_2);
8240	            }
8241	        }
8242	    }
8243	
8244	    s_sh.attached = true;
8245	    s_sh.home_idx = 0;
8246	    s_sh.ride_idx = 0;
8247	    {
8248	        int32_t last_m = myvendor_devctl_last_ride_m_get();
8249	
8250	        s_sh.last_km = (last_m > 50) ? ((float)last_m / 1000.0f) : 0.0f;
8251	    }
8252	    helm_apply_view();
8253	    helm_refresh_numbers();
8254	    helm_shell_bind_keys();
8255	    /* 换主题重建会再次进本函数：旧定时器必须先删，否则旧回调继续跑在刚被
8256	     * 重建掉的 rotbar/信息卡上。attach 全程同步（重建入口另有 s_rebuilding
8257	     * 防重入），放在创建前不会出现"本函数执行到一半被旧 timer 打断"的窗口。 */
8258	    if (s_sh.rot_timer != NULL) {
