515	static void lv_port_scroll_down(void)
516	{
517	    lv_obj_t *mbox;
518	
519	    if (helm_pwr_dialog_open()) {
520	        helm_pwr_dialog_cancel();
521	        BTN_LOG("KEY1 short -> poweroff cancel");
522	        return;
523	    }
524	
525	    mbox = lv_port_get_active_msgbox();
526	    if (mbox != NULL) {
527	        lv_msgbox_close(mbox);
528	        BTN_LOG("KEY1 short -> msgbox close");
529	        return;
530	    }
531	
532	    /*
533	     * KEY1 双击（只有页面注册了 double 回调才启用，目前是菜单主页）：**向上一个聚焦**。
534	     * ⚠ 单击必须**延后一个双击窗口**再执行 —— 否则"第一次单击已经走了一步 + 双击再走回去"
535	     * 正好抵消，双击看上去什么也没发生（KEY2 的单击/双击也是这么处理的，见
536	     * lv_port_click_confirm_page()）。没有注册 double 回调的页面保持原样：立即执行、零延迟。
537	     */
538	    if (s_ctx.page_scroll_double_cb != NULL) {
539	        const uint32_t now = lv_tick_get();
540	
541	        if (s_ctx.last_scroll_release_tick != 0 &&
542	            lv_tick_elaps(s_ctx.last_scroll_release_tick) < LV_PORT_DOUBLE_CLICK_MS) {
543	            lv_port_cancel_pending_scroll_single();
544	            s_ctx.last_scroll_release_tick = 0;
545	            s_ctx.page_scroll_double_cb(s_ctx.page_scroll_double_ud);
546	            BTN_LOG("KEY1 double -> page prev");
547	            return;
548	        }
549	
550	        s_ctx.last_scroll_release_tick = now;
551	        lv_port_cancel_pending_scroll_single();
552	        s_ctx.pending_scroll_single = lv_timer_create(
553	            lv_port_pending_scroll_single_cb, LV_PORT_DOUBLE_CLICK_MS, NULL);
554	        lv_timer_set_repeat_count(s_ctx.pending_scroll_single, 1);
555	        return;
556	    }
557	
558	    lv_port_scroll_do();
559	}
