636	static void lv_port_btn_timer(lv_timer_t *timer)
637	{
638	    btn_buttonset_t set;
639	    lv_obj_t *mbox;
640	#if MYVENDOR_LVGL_STALL_LOG
641	    uint32_t now;
642	    uint32_t gap;
643	#endif
644	
645	    LV_UNUSED(timer);
646	
647	    if (s_ctx.fd < 0) {
648	        return;
649	    }
650	
651	    if (helm_pwr_is_offing()) {
652	        s_ctx.last = lv_port_btn_read();
653	        return;
654	    }
655	
656	#if MYVENDOR_LVGL_STALL_LOG
657	    now = lv_tick_get();
658	    gap = s_btn_last_poll_tick ? lv_tick_elaps(s_btn_last_poll_tick) : 0;
659	    s_btn_last_poll_tick = now;
660	    if (gap > 80u) {
661	        LVGL_STALL("btn timer gap %ums scroll_cb=%d confirm_cb=%d",
662	            (unsigned)gap, s_ctx.page_scroll_cb != NULL,
663	            s_ctx.page_confirm_cb != NULL);
664	    }
665	#endif
666	
667	    set = lv_port_btn_read();
668	    mbox = lv_port_get_active_msgbox();
669	
670	    /* CPU load is a 1-2 second history and cannot predict the first frame
671	     * after input.  Raise the short interactive floor on both edges so a
672	     * long press release also has a fresh window for its UI callback. */
673	    if (((set ^ s_ctx.last) &
674	         (LV_PORT_BTN_SCROLL | LV_PORT_BTN_CLICK | LV_PORT_BTN_PWR)) != 0) {
675	        sf32lb_dvfs_interact();
676	    }
677	
678	    if (helm_idle_is_sleeping()) {
679	        if ((set & ~s_ctx.last) != 0) {
680	            helm_idle_wake();
681	            s_ctx.idle_swallow = true;
682	        }
683	
684	        if (s_ctx.idle_swallow) {
685	            if (set == 0) {
686	                s_ctx.idle_swallow = false;
687	            }
688	
689	            s_ctx.last = set;
690	            return;
691	        }
692	    } else {
693	        s_ctx.idle_swallow = false;
694	    }
695	
696	    if (s_ctx.had_msgbox && mbox == NULL) {
697	        s_ctx.focus_ready = false;
698	    }
699	    s_ctx.had_msgbox = (mbox != NULL);
700	
701	    if ((set & LV_PORT_BTN_SCROLL) && !(s_ctx.last & LV_PORT_BTN_SCROLL)) {
702	        s_ctx.scroll_press_tick = lv_tick_get();
703	        s_ctx.scroll_long_fired = false;
704	        myvendor_sound_key();
705	        BTN_LOG("KEY1 down set=0x%02x scroll_cb=%d", (unsigned)set,
706	            s_ctx.page_scroll_cb != NULL);
707	    }
708	
709	    if ((set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
710	        lv_port_scroll_hold_update();
711	    }
712	
713	    if (!(set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
714	        BTN_LOG("KEY1 up%s set=0x%02x held=%ums",
715	                s_ctx.scroll_long_fired ? " after-long" : "",
716	                (unsigned)set,
717	                (unsigned)lv_tick_elaps(s_ctx.scroll_press_tick));
718	        if (!s_ctx.scroll_long_fired) {
719	            lv_port_scroll_down();
720	        }
721	        s_ctx.scroll_long_fired = false;
722	    }
723	
724	    if ((set & LV_PORT_BTN_CLICK) && !(s_ctx.last & LV_PORT_BTN_CLICK)) {
725	        s_ctx.click_press_tick = lv_tick_get();
726	        s_ctx.click_long_fired = false;
727	        myvendor_sound_ok();
728	        BTN_LOG("KEY2 down set=0x%02x confirm_cb=%d", (unsigned)set,
729	            s_ctx.page_confirm_cb != NULL);
730	    }
731	
732	    if ((set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
733	        lv_port_click_hold_update();
734	    }
735	
736	    if (!(set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
737	        /* 用户 2026-09-27 要求："打印我点下的模式" ⇒ 把按下时长与判定（短/长）一起打出来。 */
738	        BTN_LOG("KEY2 up%s set=0x%02x held=%ums",
739	                s_ctx.click_long_fired ? " after-long" : "",
740	                (unsigned)set,
741	                (unsigned)lv_tick_elaps(s_ctx.click_press_tick));
742	        if (s_ctx.click_long_fired) {
743	            if (s_ctx.page_longpress2_up_cb != NULL) {
744	                s_ctx.page_longpress2_up_cb(s_ctx.page_longpress2_up_ud);
745	            }
746	        } else {
747	            lv_port_click_confirm();
748	        }
749	        s_ctx.click_long_fired = false;
750	    }
751	
752	    if ((set & LV_PORT_BTN_PWR) && !(s_ctx.last & LV_PORT_BTN_PWR)) {
753	        s_ctx.pwr_press_tick = lv_tick_get();
754	        s_ctx.pwr_long_fired = false;
755	        myvendor_sound_key();
756	        BTN_LOG("PWR down set=0x%02x", (unsigned)set);
757	    }
758	
759	    if ((set & LV_PORT_BTN_PWR) && (s_ctx.last & LV_PORT_BTN_PWR)) {
760	        lv_port_pwr_hold_update();
761	    }
762	
763	    if (!(set & LV_PORT_BTN_PWR) && (s_ctx.last & LV_PORT_BTN_PWR)) {
764	        BTN_LOG("PWR up%s set=0x%02x",
765	                s_ctx.pwr_long_fired ? " after-long" : "",
766	                (unsigned)set);
767	        if (!s_ctx.pwr_long_fired) {
768	            helm_pwr_on_click();
769	        }
770	        s_ctx.pwr_long_fired = false;
771	    }
772	
773	    s_ctx.last = set;
774	}
