5808	static void map_will_appear(void * pm_page)
5809	{
5810	    map_page_t * map = live_map_page_instance();
5811	    lv_pm_page_t page = lv_pm_get_pm_page(pm_page);
5812	    const bool from_menu = (s_cover_page_id == (lv_pm_id)BICYCLE_PM_ID_MENU);
5813	
5814	    s_cover_page_id = 0xffu;
5815	
5816	    if (page && page->page) {
5817	        lv_obj_clear_flag(page->page, LV_OBJ_FLAG_HIDDEN);
5818	    }
5819	
5820	    /* 页面级选项：`lv_pm_close_page_msg()` 在回调完 will_appear 后会给**本页**
5821	     * 播 ENTER（用这里装的 open_options），所以选项要在这里定。
5822	     *
5823	     * - 菜单返回：`bicycle_page_anima.c` 的口径是"菜单进出口都不加动画"
5824	     *   （MENU 那一行 no_anima 只管菜单自己的进出，回程露出的主界面仍会用
5825	     *   MAP 行的 220 ms fade）。这里改走 apply_silent() ⇒ 主界面一帧内整页可见。
5826	     * - 开机 splash / USB / 工厂页返回：保持原来的 220 ms 淡入。
5827	     * - 开机首轮（s_boot_deferred）沿用 apply_silent()，不抢 splash。 */
5828	    if (!s_boot_deferred && page != NULL) {
5829	        if (from_menu) {
5830	            /* 菜单覆盖时主界面自己的 EXIT 也走了 fade（`lv_pm_anima` 用的是页面
5831	             * 自己的 open_options），页根 opa 停在 0；no_anima 的 appear 只清
5832	             * HIDDEN / 摆正位置，不碰 opa ⇒ 这里必须显式复位，否则整页透明。 */
5833	            if (page->page != NULL) {
5834	                lv_obj_set_style_opa(page->page, LV_OPA_COVER, 0);
5835	            }
5836	            bicycle_page_anima_apply_silent(page);
5837	        } else {
5838	            bicycle_page_anima_apply(page, BICYCLE_PM_ID_MAP);
5839	        }
5840	    }
5841	
5842	    if (map) {
5843	        helm_shell_bind_keys();
5844	    }
5845	
5846	    /* 主界面入场动效（WP-V3）：时钟块 → 状态列 → 操作条错峰淡入 + 轻推入。
5847	     *
5848	     * 选点理由：本页只有在**栈顶**（splash 已经走完 400 ms 淡出、被 no_anima
5849	     * 关闭）时才会走到 will_appear —— lv_pm_close_page_msg() 里先隐藏/删除
5850	     * splash 页，再回调前一页的 will_appear，所以这里起播不会和 splash 抢帧。
5851	     * 开机首轮 push（splash 底下建空壳）也走本回调，但那时 helm_shell 还没
5852	     * attach（s_sh.attached=false），函数内部直接返回，不会误播。
5853	     * 与页面级 fade 的关系：fade 动的是页根（这里的 page->page）的 opa，
5854	     * 入场动效动的是三个子控件的 opa/translate_y，两条通道互不覆盖；
5855	     * 子级不透明度与父级相乘、都收敛到 255，末态由 helm_sb_in_done 显式复位。
5856	     *
5857	     * 菜单返回不重播：用户要的是"返回即完整"（WP-FADE/R1）。三块卡片在菜单
5858	     * 打开前就已停在末态，菜单覆盖期间也没被改过；重播会让地图已经出来了、
5859	     * 卡片却还从 opa=0 淡入，观感仍是"返回有动画"。换主题的重建路径
5860	     * （`helm_shell_rebuild_once()` 末尾）会自己再调本函数，不受影响。 */
5861	    if (!from_menu) {
5862	        helm_shell_enter_anim();
5863	    }
5864	}
