static void dial_build(void)
{
    memset(&UD, 0, sizeof(UD));
    s_screen = SCR_DIAL;
    d_bg(s_scr, P_PAPER);
    /* 环形页与骑行三页共用同一条状态栏（y=0..24）。 */
    statusbar_build();

    UD.cx = DIAL_CX;
    UD.cy = DIAL_CY;
    UD.d = DIAL_D;
    s_angle = s_mode * 90;
    UD.angle = s_angle;

    /* 整圈未选轨道 + 选中扇区（浅 20% + 深色 2px 外沿）。 */
    UD.ring = RING(s_scr, UD.cx, UD.cy, UD.d, 2, P_TRACK);
    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);

    /* 24 刻度：每 15°，整点 3px。 */
    for (int i = 0; i < 24; i++) {
        const bool major = (i % 6 == 0);

        UD.tick[i] = LINE(s_scr, UD.tick_pts[i], 2, major ? 3 : 1,
                          major ? P_INK : P_TICK);
    }
    /* 舵柄：中心到外圈 + 8px 横杆。 */
    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
    UD.cross = LINE(s_scr, UD.cross_pts, 2, 3, P_INK);

    /* 盘心：图标底 + 模式名 / 描述 / 主值 / 副行，装进一个容器方便整体淡入。 */
    UD.hub = lv_obj_create(s_scr);
    lv_obj_remove_style_all(UD.hub);
    lv_obj_set_pos(UD.hub, 40, 84);
    lv_obj_set_size(UD.hub, 160, 108);
    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_CLICKABLE);

    {
        /* 标题：文字 160 宽居中；20px 图标由 dial_title_layout() 摆到左侧。 */
        UD.chip = NULL;
        UD.icon = hfi_create_px(UD.hub, mode_icon(s_mode), 20, 0, 0,
                                C_DEEP[s_mode]);
        UD.name = LW(UD.hub, "", PX_TITLE, P_INK, 0, 0, 160,
                     LV_TEXT_ALIGN_CENTER);
    }
    UD.desc = LW(UD.hub, "", PX_SMALL, P_MUTE, 0, 38, 160,
                 LV_TEXT_ALIGN_CENTER);
    {
        /* 22px 数字 + 11px 单位：共用基线（hub_value_layout）。 */
        UD.value = L(UD.hub, "", PX_VALUE, P_INK, 0, 55);
        UD.unit = L(UD.hub, "", PX_MICRO, P_MUTE, 0, 66);
    }
    HAIR(UD.hub, 64, 87, 32);
    UD.sub = LW(UD.hub, "", PX_MICRO, P_MUTE, 0, 92, 160,
                LV_TEXT_ALIGN_CENTER);

    /* 模式名：4 个方位，选中 15px。半径 99：文字墨迹内缘 r≈83，
     * 与舵柄最外墨迹 r≈73 留 10px 安全距（脚本断言见证据）。 */
    {
        static const int lx[4] = { 0, 1, 0, -1 };
        static const int ly[4] = { -1, 0, 1, 0 };

        for (int i = 0; i < 4; i++) {
            UD.labels[i] = LW(s_scr, mode_name(i), PX_SMALL, P_MUTE,
                              DIAL_CX + lx[i] * 99 - 20,
                              DIAL_CY + ly[i] * 99 - 8,
                              40, LV_TEXT_ALIGN_CENTER);
        }
    }

    /* 状态（记录/暂停/导航）由顶部状态栏徽章表达，盘面不再重复文字。 */

    dial_week_strip();
    dial_content(s_mode);
    dial_geometry(DIAL_CX, DIAL_CY, DIAL_D, 255);
}

/* ── 盘面旋转（ANIMATION #1/#2）────────────────────────────────── */

static lv_anim_t *s_rot_anim;
static int32_t s_rot_p;
static int s_rot_a0, s_rot_a1;
static int s_rot_oa0, s_rot_ob0;
static int s_rot_oa_cur = 255, s_rot_ob_cur;
static int s_rot_from_mode, s_rot_to_mode;
static bool s_rot_swapped;

static void rot_exec(void *var, int32_t p)
{
    (void)var;
    s_angle = s_rot_a0 + (s_rot_a1 - s_rot_a0) * (int)p / 1000;
    UD.angle = s_angle;
    dial_pointer_layout(s_angle);
    s_rot_oa_cur = s_rot_oa0 * (1000 - (int)p) / 1000;
    s_rot_ob_cur = s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000;
    SET_ARC_OPA(UD.fill, s_rot_oa_cur);
    SET_ARC_OPA(UD.trk, s_rot_oa_cur);
    SET_ARC_OPA(UD.fill2, s_rot_ob_cur);
    SET_ARC_OPA(UD.trk2, s_rot_ob_cur);
    if (!s_rot_swapped && p >= 500) {
        s_rot_swapped = true;
        dial_content(s_rot_to_mode);
    }
}

static void rot_ready(lv_anim_t *a)
{
    (void)a;
    s_rot_anim = NULL;
    if (UD.fill != NULL) {
        lv_obj_delete(UD.fill);
        lv_obj_delete(UD.trk);
    }
    UD.fill = UD.fill2;
    UD.trk = UD.trk2;
    UD.fill2 = NULL;
    UD.trk2 = NULL;
    SET_ARC_OPA(UD.fill, 255);
    SET_ARC_OPA(UD.trk, 255);
    s_mode = s_rot_to_mode;
    s_angle = s_rot_a1;
    UD.angle = s_angle;
    dial_pointer_layout(s_angle);
    dial_content(s_mode);
    s_busy = false;
}

/** 环形页旋转：dir = +1 顺时针（→ 键），-1 逆时针（← 键）。
 * 目标角取 to_mode*90 加上足够圈数，保证朝正确方向转；可被下一次按键打断。 */
static void dial_rotate(int dir)
{
    int from_mode;
    int to_mode;
    int a0;
    int target;
    int duration = 160;
    lv_anim_t a;
    if (dir == 0) {
        dir = 1;
    }

    /* 转场中禁止再转；但盘面旋转本身可以被下一次按键打断（#2）。 */
    if (UD.fill == NULL || (s_busy && s_tr_anim != NULL)) {
        return;
    }
    a0 = (int)s_angle;

    if (s_rot_anim != NULL) {
        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
        lv_anim_delete(&s_rot_p, NULL);
        s_rot_anim = NULL;
        if (UD.fill != NULL) {
            lv_obj_delete(UD.fill);
            lv_obj_delete(UD.trk);
        }
        UD.fill = UD.fill2;
        UD.trk = UD.trk2;
        UD.fill2 = NULL;
        UD.trk2 = NULL;
        from_mode = s_rot_to_mode;
        s_rot_oa0 = s_rot_oa_cur;
        s_rot_ob0 = s_rot_ob_cur;
        s_mode = from_mode;
        duration = 120;
    } else {
        from_mode = s_mode;
        s_rot_oa0 = 255;
        s_rot_ob0 = 0;
    }
    s_rot_oa_cur = s_rot_oa0;
    s_rot_ob_cur = s_rot_ob0;
    to_mode = (from_mode + (dir > 0 ? 1 : -1) + M_COUNT) % M_COUNT;

    target = to_mode * 90;
    if (dir > 0) {
        while (target <= a0) {
            target += 360;
        }
    } else {
        while (target >= a0) {
            target -= 360;
        }
    }

    s_rot_a0 = a0;
    s_rot_a1 = target;
    s_rot_from_mode = from_mode;
    s_rot_to_mode = to_mode;
    s_rot_swapped = false;
    dial_sector(to_mode, (lv_opa_t)s_rot_ob0, &UD.fill2, &UD.trk2);

    s_busy = true;
    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_rot_p);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, duration);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_set_exec_cb(&a, rot_exec);
    lv_anim_set_ready_cb(&a, rot_ready);
    s_rot_anim = lv_anim_start(&a);
}

/* ── 骑行页 ────────────────────────────────────────────────────── */

/* 前方 2 km 海拔剖面。采样点数、段数、跳色阈值、三角填充 + 2px 脊线都
 * 沿用旧 UI（helm_shell.c 的 HELM_CLIMB_PROF_N / helm_climb_grade_zone /
 * helm_climb_paint_seg）。数据是**假数据**：按分段目标坡度累加，不是 GPX。 */
static double s_elev[ELEV_PROF_N];

 *
 * 两簇对齐（按**墨迹**而不是对象框）：
 *   左簇：时间 + GPS BLE 心率 功率 踏频，墨迹 x0=12，时间→GPS 8px，图标间 4px；
 *   右簇：REC + NAV + 电量，墨迹 x1=216，REC→NAV 4px，NAV→电量 8px，
 *         电量图标→文字 7px；NAV/REC 隐藏时整簇右移（间隙不变）；
 *   两簇之间弹性空白（space-between）。
 *
 * 图标是**原生 14px** 位图（helm_icons_14.c），不再把 20px 字形用
 * transform_scale 缩放（6× 下会糊成一团）。每个字形的墨迹宽/偏置集中在
 * 下面的 SB_INK[]，数值全部实测——改字形后必须重测：
 * docs/agent/evidence/WP-HELM9/R1/A/statusbar_coords.md（measure.py 生成）。
 */
#define SB_ICON_PX          14
#define SB_INK_GAP_TIME     8
#define SB_INK_GAP_ICON     4
#define SB_INK_GAP_REC_NAV  4
#define SB_INK_GAP_NAV_BAT  8
#define SB_INK_GAP_BAT_TXT  7
#define SB_REC_D            5      /* REC 实心点直径 */
#define SB_TIME_X           12
#define SB_BAT_TXT_X        193
#define SB_BAT_TXT_W        24
#define SB_MIN_BLANK        12

enum { SB_GPS, SB_BLE, SB_HR, SB_PWR, SB_CAD, SB_NAV, SB_BAT, SB_ICON_N };

/* 14px 字形墨迹：ink_w = 墨迹宽（BLE 含 3px 连接点）；
 * cx_off = 对象中心 − 墨迹左沿（补偿 side bearing）；
 * dot_dx = 连接点墨迹左沿 − 字形墨迹左沿（-1 = 不画点）。 */
typedef struct {
    helm_icon_t id;
    int ink_w;
    int cx_off;
    int dot_dx;
} sb_ink_t;

static const sb_ink_t SB_INK[SB_ICON_N] = {
    [SB_GPS] = { HELM_ICON_GPS,     14, 7, 11 },
    [SB_BLE] = { HELM_ICON_BLE,     13, 4, 10 },  /* 7 字形 + 3 + 3 点 */
    [SB_HR]  = { HELM_ICON_HR,      12, 6, -1 },
    [SB_PWR] = { HELM_ICON_POWER,    9, 5, -1 },
    [SB_CAD] = { HELM_ICON_CADENCE, 10, 5, -1 },
    [SB_NAV] = { HELM_ICON_NAV,     10, 5, -1 },
    [SB_BAT] = { HELM_ICON_BATTERY, 12, 6, -1 },
};

typedef struct {
    lv_obj_t *time_l;
    lv_obj_t *batt_l;
    lv_obj_t *batt_i;
    lv_obj_t *rec_dot;
    lv_obj_t *nav_i;
} statusbar_ui_t;

static statusbar_ui_t SB;

static void status_dot(lv_obj_t *p, int x, int y, int d, uint32_t col,
                       bool hollow)
{
    lv_obj_t *o = B(p, x, y, d, d, col,
                    hollow ? LV_OPA_TRANSP : LV_OPA_COVER, d / 2);

    if (hollow) {
        lv_obj_set_style_border_width(o, 1, 0);
        lv_obj_set_style_border_color(o, lv_color_hex(col), 0);
        lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    }
}

/** 原生 14px 图标：对象中心 = 墨迹左沿 + cx_off（表驱动，无缩放）。 */
static lv_obj_t *sb_icon(lv_obj_t *p, int k, int ink_x0, uint32_t col)
{
    const sb_ink_t *g = &SB_INK[k];

    return hfi_create_px(p, g->id, SB_ICON_PX, ink_x0 + g->cx_off, 12, col);
}

/** 按“墨迹左沿”放一个 14px 图标 + 可选连接点。 */
static void icon_at_ink(int k, int ink_x0, bool on)
{
    uint32_t col = on ? P_INK : P_TRACK;

    (void)sb_icon(s_scr, k, ink_x0, col);
    if (SB_INK[k].dot_dx >= 0) {
        status_dot(s_scr, ink_x0 + SB_INK[k].dot_dx, 16, 3, col, !on);
    }
}

/** 左簇墨迹布局：返回左簇最后一个墨迹 x1；pos[] 为各图标墨迹 x0（-1=隐藏）。 */
static int left_cluster_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
                               int pos[5])
{
    const bool on[5] = { true, ble, hr, pwr, cad };
    int x = x0;
    int end = x - 1;

    for (int i = 0; i < 5; i++) {
        if (!on[i]) {
            pos[i] = -1;
            continue;
        }
        pos[i] = x;
        end = x + SB_INK[i].ink_w - 1;
        x = end + 1 + SB_INK_GAP_ICON;
    }
    return end;
}

/** 右簇：从电量文字墨迹左沿往左排（pos[] = REC/NAV/电量 的墨迹 x0，-1=隐藏）；
 *  返回右簇最左墨迹 x0。 */
static int right_cluster_layout(bool rec, bool nav, int txt_x0, int pos[3])
{
    int x = txt_x0 - SB_INK_GAP_BAT_TXT;   /* 电量图标的墨迹右侧（不含） */
    int left;

    pos[2] = x - SB_INK[SB_BAT].ink_w;
    left = pos[2];
    x = pos[2] - SB_INK_GAP_NAV_BAT;
    pos[1] = nav ? x - SB_INK[SB_NAV].ink_w : -1;
    if (nav) {
        left = pos[1];
        x = pos[1] - SB_INK_GAP_REC_NAV;
    }
    pos[0] = rec ? x - SB_REC_D : -1;
    if (rec) {
        left = pos[0];
    }
    return left;
}

/** 电量字形分级：<20% 空、20..59% 半、≥60% 满（三者墨迹包围盒相同，位置不跳）。 */
static helm_icon_t batt_glyph(void)
{
    if (s_batt < 20) {
        return HELM_ICON_BATT_EMPTY;
    }
    if (s_batt < 60) {
        return HELM_ICON_BATT_HALF;
    }
    return HELM_ICON_BATTERY;
}

static void statusbar_refresh(void)
{
    char buf[16];
    const bool low = s_batt < 20;
    const uint32_t bcol = low ? P_RED : P_INK;

    if (SB.time_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(SB.time_l, buf);

    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(SB.batt_l, buf);
    lv_obj_set_style_text_color(SB.batt_l, lv_color_hex(bcol), 0);
    lv_obj_set_style_text_color(SB.batt_i, lv_color_hex(bcol), 0);
    hfi_set(SB.batt_i, batt_glyph());

    /* REC：记录中红点；暂停变灰；未记录隐藏。 */
    if (SB.rec_dot != NULL) {
        if (R.active && R.rec) {
            lv_obj_remove_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_bg_color(SB.rec_dot,
                                      lv_color_hex(R.paused ? P_TRACK : P_RED),
                                      0);
        } else {
            lv_obj_add_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
        }
    }
    /* NAV：导航中显示（深蓝），未导航隐藏。 */
    if (SB.nav_i != NULL) {
        if (s_nav_active) {
            lv_obj_remove_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_text_color(SB.nav_i,
                                        lv_color_hex(C_DEEP[M_NAV]), 0);
        } else {
            lv_obj_add_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

/** 建状态栏（环形页与骑行三页共用）。 */
static void statusbar_build(void)
{
    char tbuf[16];
    int time_end;
    int pos[5];
    int rpos[3];
    bool show_ble = true;
    bool cluster_off = !s_sens_on[0] && !s_sens_on[1] && !s_sens_on[2];
    bool show_hr = !cluster_off;
    bool show_pwr = !cluster_off;
    bool show_cad = !cluster_off;
    bool show_nav = s_nav_active;
    bool show_rec = R.active && R.rec;
    int left_end;
    int right_left;
    int txt_x0;
    int x0;

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* ① 时间：墨迹 x0=12（12px，贴左）。 */
    snprintf(tbuf, sizeof(tbuf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, tbuf, 12, P_INK, SB_TIME_X, 4,
                   text_width(tbuf, 12) + 2, LV_TEXT_ALIGN_LEFT);
    time_end = SB_TIME_X + text_width(tbuf, 12) - 1;

    /* ② 电量文字（右对齐到墨迹 x1=216）先算：右簇从它往左排。 */
    snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
    txt_x0 = SB_BAT_TXT_X + SB_BAT_TXT_W - text_width(tbuf, 10);

    /* ③ 左簇墨迹布局 + 碰撞保护（隐藏顺序 踏频→功率→NAV→BLE）。 */
    x0 = time_end + 1 + SB_INK_GAP_TIME;
    for (int guard = 0; guard < 5; guard++) {
        left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr,
                                       show_cad, pos);
        right_left = right_cluster_layout(show_rec, show_nav, txt_x0, rpos);
        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
            break;
        }
        if (show_cad) {
            show_cad = false;
            printf("helm: statusbar collision -> hide cadence\n");
        } else if (show_pwr) {
            show_pwr = false;
            printf("helm: statusbar collision -> hide power\n");
        } else if (show_nav) {
            show_nav = false;
            printf("helm: statusbar collision -> hide NAV\n");
        } else if (show_ble) {
            show_ble = false;
            printf("helm: statusbar collision -> hide BLE\n");
        } else {
            break;
        }
    }
    left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr, show_cad,
                                   pos);
    right_left = right_cluster_layout(show_rec, show_nav, txt_x0, rpos);

    if (pos[0] >= 0) {
        icon_at_ink(SB_GPS, pos[0], s_gps > 0);
    }
    if (pos[1] >= 0) {
        icon_at_ink(SB_BLE, pos[1], s_ble_on);
    }
    if (pos[2] >= 0) {
        icon_at_ink(SB_HR, pos[2], s_sens_on[0]);
    }
    if (pos[3] >= 0) {
        icon_at_ink(SB_PWR, pos[3], s_sens_on[2]);
    }
    if (pos[4] >= 0) {
        icon_at_ink(SB_CAD, pos[4], s_sens_on[1]);
    }

    /* ④ 右簇：REC / NAV / 电量从右往左排（墨迹间隙固定，隐藏时自动右移）。 */
    SB.batt_i = sb_icon(s_scr, SB_BAT, rpos[2],
                        s_batt < 20 ? P_RED : P_INK);
    if (rpos[1] >= 0) {
        SB.nav_i = sb_icon(s_scr, SB_NAV, rpos[1], C_DEEP[M_NAV]);
    }
    if (rpos[0] >= 0) {
        SB.rec_dot = B(s_scr, rpos[0], 9, SB_REC_D, SB_REC_D, P_RED,
                       LV_OPA_COVER, 2);
    }
    snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
    SB.batt_l = LW(s_scr, tbuf, 10,
                   s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 6,
                   SB_BAT_TXT_W, LV_TEXT_ALIGN_RIGHT);

    statusbar_refresh();
}

