/* ── 导航页（真 vmap）─────────────────────────────────────────── */

static void nav_stop(void)
{
#ifdef SIM_WITH_UI
    if (s_nav_timer != NULL) {
        lv_timer_delete(s_nav_timer);
        s_nav_timer = NULL;

                R.still_s = 0;
                if (R.paused) {
                    R.speed = 0.0;
                    R.cadence = 0;
                    R.power = 0;
                }
                s_busy = false;
                rebuild();
            }
            break;
        case LP_BACK:
            /* 骑行页左长按返回环形页：本次记录继续（不停表）。 */
            keylog("KEY%d long -> back (record continues)", LP.key);
            go_back();
            break;
        case LP_NAV_CTRL:
            if (s_nav_active) {
                s_sub_sel = 0;
                s_screen = SCR_NAV_LIVE;
            } else {
                s_screen = SCR_ELEVATION;
            }
            s_busy = false;
            rebuild();
            break;
        case LP_GRADE_ZERO:
            s_grade_off_x10 = -42;
            toast("坡度已归零");
            s_busy = false;
            rebuild();
            break;
        case LP_TOGGLE_RIDE:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            toggle_ride();
            if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
                rebuild();
            }
            break;
        default:
            break;
    }
}

/* 长按不画进度条/弧：到 800 ms 直接执行（页面切换/弹窗本身就是明确结果）。 */
static void lp_tick(void)
{
    if (!LP.active) {
        return;
    }
    if (lv_tick_get() - LP.t0 >= LP.dur) {
        lp_fire();
    }
}

static void lp_begin(int key)
{
    LP.active = true;
    LP.key = key;
    LP.t0 = lv_tick_get();
    LP.dur = KEY_LONG_MS;
    if (key == 2 && s_screen == SCR_DIAL) {
        LP.target = LP_TOGGLE_RIDE;      /* 环形页右长 → 进入骑行 */
    } else if (key == 2 && s_screen == SCR_RIDE) {
        LP.target = LP_PAUSE;            /* 骑行页右长 → 暂停 */
    } else if (key == 1 && s_screen == SCR_DIAL) {
        LP.target = LP_ENTER;            /* 环形页左长 → 进入当前选项 */
    } else if (key == 1 && s_screen == SCR_RIDE) {
        LP.target = LP_BACK;             /* 骑行页左长 → 返回环形（记录继续） */
    } else if (screen_is_setlist(s_screen)) {
        LP.target = (key == 1) ? LP_BACK : LP_ACTIVATE;  /* ←长返回 / →长确定 */
    } else if (key == 1 && s_screen == SCR_NAV) {
        LP.target = LP_NAV_CTRL;
    } else if (key == 1 && s_screen == SCR_GRADECAL) {
        LP.target = LP_GRADE_ZERO;
    } else {
        LP.target = LP_ACTIVATE;
    }
}

/* 前向声明 */
static void rebuild(void);
static void go_back(void);

static void do_short(int key)
{
    /* 关机确认/进度由弹窗或 data_tick 管；这里不再处理。 */
    if (s_screen == SCR_SHUTDOWN) {
        return;
    }

    /* 设置列表：← 上移，→ 下移（长按见 lp_begin：左=返回，右=确定）。 */
    if (screen_is_setlist(s_screen)) {
        setl_move(key == 1 ? -1 : 1);
        return;
    }

    if (s_screen == SCR_RIDE) {
        if (R.active && R.paused) {
            if (key == 1) {
                keylog("KEY1 click (paused) -> back, record continues");
                go_back();
            } else {
                keylog("KEY2 click (paused) -> save?");
                s_modal = MODAL_SAVE_ASK;
                s_modal_key = 0;
                s_busy = false;
                rebuild();
            }
        } else {
            /* 骑行三页：← 上一页 / → 下一页（循环，不轮转自转）。 */
            s_ride_page = (s_ride_page + ((key == 2) ? 1 : 2)) % 3;
            keylog("KEY%d click -> ride page %d/%d", key, s_ride_page + 1, 3);
            s_busy = false;
            rebuild();
        }
        return;
    }

    if (s_screen == SCR_DIAL) {
        keylog("KEY%d click -> dial %s", key, key == 1 ? "CCW" : "CW");
        dial_rotate(key == 1 ? -1 : 1);
        return;
    }

    if (key == 1) {
        switch (s_screen) {
            case SCR_NAV:
                /* 导航页 KEY1 短：路线来源（GPX / 坐标点 / 常用点）；
                 * KEY1 长：导航中 → 本次导航；未导航 → 海拔详情。 */
                s_sub_sel = 0;
                s_screen = SCR_ROUTE_SRC;
                s_busy = false;
                rebuild();
                break;
            case SCR_RECORD:
                if (s_rec_sel + 1 < (s_rec_n < 4 ? s_rec_n : 4)) {
                    s_rec_sel++;
                    rec_sel_move(true);
                    rec_rows();
                }
                break;
            case SCR_ABOUT:
                s_about_sel = (s_about_sel + 1) % 5;
                about_focus_apply();
                break;
            default:
                break;
        }
    } else {
        go_back();
    }
}

/* ── 电源键（键盘 ↑）────────────────────────────────────────────────
 *
 *   单击（<400 ms）       无反应（只记日志；双击的第一次）
 *   双击（间隔 <300 ms）  熄屏（SCR_IDLE）
 *   长按（≥800 ms）       弹「确认关机？」（← 取消 / → 确认）
 *   熄屏 / 关机黑屏       按任意键或触摸唤醒；这一次输入不触发功能

                s_busy = false;
                rebuild();
            }
            break;
        default:
            break;
    }
}

static void modal_key_event(int key, bool down)
{
    if (key == 3) {
        keylog("modal: POWER ignored (modal)");
        return;
    }
    if (down) {
        if (s_modal_key == 0) {
            s_modal_key = key;
            s_modal_t0 = lv_tick_get();
        }
        return;
    }
    if (key != s_modal_key) {
        return;
    }
    s_modal_key = 0;
    if (lv_tick_get() - s_modal_t0 >= KEY_CLICK_MS) {
        keylog("modal: KEY%d press ignored (not a click)", key);
        return;
    }
    modal_action(key);
}

/* ── 电源键状态机 ──────────────────────────────────────────────── */

static void pwr_event(bool down)
{
    if (down) {
        if (PWR.down) {
            return;             /* 自动重复已在上游去重，这里兜底 */
        }
        if (s_screen == SCR_IDLE ||
            (s_screen == SCR_SHUTDOWN && s_power_phase == 2)) {
            const scr_t from = s_screen;

            pwr_wake();
            PWR.consume_up = true;
            keylog("POWER click -> wake from %s (input consumed)", SCR_NAME[from]);
            return;
        }
        if (s_screen == SCR_SHUTDOWN) {
            PWR.consume_up = true;
            keylog("POWER down ignored (shutdown phase %d)", s_power_phase);
            return;
        }
        if (LP.active) {
            PWR.consume_up = true;
            keylog("POWER down ignored (LP active)");
            return;
        }
        PWR.down = true;
        PWR.fired = false;
        PWR.t0 = lv_tick_get();
        /* 双击判定：距上一次单击松手 <300 ms，则这次是双击的第二下。 */
        PWR.dbl = PWR.last_click_valid &&
                  (PWR.t0 - PWR.last_click < KEY_DBL_MS);
        keylog("POWER down screen=%s dbl=%d", SCR_NAME[s_screen],
               PWR.dbl ? 1 : 0);
        return;
    }

    if (PWR.consume_up) {
        PWR.consume_up = false;
        keylog("POWER up consumed (wake)");
        return;
    }
    if (!PWR.down) {
        return;
    }
    PWR.down = false;
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        if (PWR.fired) {
            PWR.fired = false;
            PWR.last_click_valid = false;
            keylog("POWER up held=%ums (long already fired)", held);
            return;
        }
        if (held < KEY_CLICK_MS) {
            if (PWR.dbl) {
                PWR.last_click_valid = false;
                keylog("POWER double click (gap<300ms) -> sleep");
                pwr_sleep();
            } else {
                PWR.last_click_valid = true;
                PWR.last_click = lv_tick_get();
                keylog("POWER click held=%ums (no-op)", held);
            }
        } else {
            PWR.last_click_valid = false;
            keylog("POWER press cancelled held=%ums", held);
        }
    }
}

static void pwr_tick(void)
{
    if (!PWR.down || PWR.fired) {
        return;
    }
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        if (held >= KEY_LONG_MS) {
            PWR.fired = true;
            PWR.last_click_valid = false;
            keylog("POWER long held=%ums -> shutdown popup", held);
            modal_open(MODAL_SHUTDOWN);
        }
    }
}

static int s_wake_swallow;   /* 唤醒那一下的抬起要吃掉，不能触发单击 */

static void ui_tick(lv_timer_t *t)
{
    (void)t;
    if (s_touch_wake) {
        s_touch_wake = false;
        if (s_screen == SCR_IDLE) {
            keylog("TOUCH click -> wake from idle");
            pwr_wake();
        }
    }
    for (;;) {
        int key = 0;
        bool down = false;

        if (!sim_display_take_key_event(&key, &down)) {
            break;
        }
        s_idle_s = 0;
        /* 唤醒输入整对吃掉：按下唤醒，抬起不再算单击。 */
        if (!down && s_wake_swallow == key) {
            s_wake_swallow = 0;
            keylog("KEY%d up consumed (wake)", key);
            continue;
        }
        if (s_screen == SCR_IDLE) {
            if (down) {
                s_wake_swallow = key;
                keylog("KEY%d click -> wake from idle", key);
                pwr_wake();
            }
            continue;
        }
        if (key == 3) {
            if (s_modal != MODAL_NONE) {
                /* 弹窗模态：电源键不触发新动作，但按住长按打开弹窗的那次
                 * 抬起必须继续走 PWR 状态机，否则 PWR.down 会永远卡住。 */
                if (down) {
                    PWR.consume_up = true;
                    keylog("POWER down ignored (modal)");
                } else {
                    pwr_event(false);
                }
                continue;
            }
            pwr_event(down);    /* 电源键有自己的单击/双击/长按，不参与 LP */
            continue;
        }
        if (s_modal != MODAL_NONE) {
            modal_key_event(key, down);
            continue;
        }
        if (s_screen == SCR_SHUTDOWN) {
            keylog("KEY%d ignored (shutdown phase %d)", key, s_power_phase);
            continue;
        }
        keylog("KEY%d %s screen=%s", key, down ? "down" : "up",
               SCR_NAME[s_screen]);
        if (s_busy) {
            const bool dial_rot =
                (s_screen == SCR_DIAL && s_tr_anim == NULL && s_rot_anim != NULL);

            if (!(dial_rot && (key == 1 || key == 2))) {
                continue;
            }
        }
        if (down) {
            if (LP.active) {
                continue;
            }
            if ((key == 1 && screen_has_lp1()) ||
                (key == 2 && screen_has_lp2())) {

                (key == 2 && screen_has_lp2())) {
                lp_begin(key);
            } else {
                do_short(key);
            }
        } else {
            if (LP.active && LP.key == key) {
                const uint32_t held = lv_tick_get() - LP.t0;

                if (held < KEY_CLICK_MS) {
                    LP.active = false;
                    keylog("KEY%d click held=%ums", key, held);
                    do_short(key);
                } else {
                    LP.active = false;
                    keylog("KEY%d press cancelled held=%ums", key, held);
                }
            }
        }
    }
    lp_tick();
    pwr_tick();
    /* 振动唤醒（模拟器钩子）：熄屏满 SIM_HELM_VIBRATE_MS 毫秒后震动一次。 */
    if (s_screen == SCR_IDLE && s_vib_ms != 0 && s_sleep_t0 != 0 &&
        lv_tick_get() - s_sleep_t0 >= s_vib_ms) {
        keylog("VIBRATE -> wake");
        pwr_wake();
    }
    if (s_toast_until != 0 && lv_tick_get() > s_toast_until) {
        s_toast_until = 0;
        if (!LP.active) {
            hint_clear();
        }
    }
    tour_tick();
}

