    if (s_sens_ticks >= 3) {
        const int i = s_sens_search;

        s_sens_search = -1;
        s_sens_on[i] = true;
        s_sens_bars[i] = 4;
        if (s_sens_dev[i][0] == '\0' || strcmp(s_sens_dev[i], "—") == 0) {
            snprintf(s_sens_dev[i], sizeof(s_sens_dev[0]), "%s",
                     SENS_NEARBY[i][0]);
