static void ride_start(void)
{
    memset(&R, 0, sizeof(R));
    R.active = true;
    R.rec = true;           /* 骑行默认开记录（REC） */
    s_ride_page = 0;        /* 新骑行从第 1 页（表盘）开始 */
    R.seed = 0x2468ACEu;
    R.speed = 0.0;
    R.hr = 126;
    R.cadence = 78;
    R.elevation = 326;
    R.power = 150;
    ride_step();
    ride_step();
    R.elapsed_s = 2;    /* 两次初始化推进也算 2 秒 */
}

static void ride_finish(void)
{
    char date[16];
    char sub[24];
    rec_t r;
    int hmax = 1;

    if (!R.active) {
        return;
    }
    R.active = false;
    R.paused = false;
    R.auto_paused = false;
    R.rec = false;
    R.still_s = 0;

    snprintf(date, sizeof(date), "10/29 周四");
    snprintf(sub, sizeof(sub), "%u:%02u · %.1f",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60),
             R.avg);
    memset(&r, 0, sizeof(r));
    snprintf(r.date, sizeof(r.date), "%s", date);
    snprintf(r.sub, sizeof(r.sub), "%s", sub);
    r.dist = R.dist_km > 0.1 ? R.dist_km : 0.1;
    for (int i = 0; i < 5; i++) {
        if (R.hist[i] > hmax) {
            hmax = R.hist[i];
        }
    }
    for (int i = 0; i < 5; i++) {
        r.bars[i] = 10 + (R.hist[i] * 28) / hmax;
        if (r.bars[i] < 10) r.bars[i] = 10;
    }
    if (s_rec_n < (int)(sizeof(s_recs) / sizeof(s_recs[0]))) {
        s_rec_n++;
    }
    memmove(&s_recs[1], &s_recs[0],
            (size_t)(s_rec_n - 1) * sizeof(s_recs[0]));
    s_recs[0] = r;
    s_week[6] += r.dist;

    {
        char msg[64];

        snprintf(msg, sizeof(msg), "已保存 · %.1f %s · %u:%02u",
                 conv_dist(r.dist), unit_dist(),
                 (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
        toast(msg);
    }
}

static void toggle_ride(void)
{
    if (R.active) {
        /* 骑行中盘面再长按 2：进入骑行页；结束走「暂停 → 右键单击 →
         * 保存 / 丢弃」。若本次骑行处于暂停态，从环形页再进来先恢复计时，
         * 否则无键可继续。 */
        if (R.paused) {
            R.paused = false;
            R.auto_paused = false;
            R.still_s = 0;
        }
        s_screen = SCR_RIDE;
        s_busy = false;
    } else {
        ride_start();
        s_screen = SCR_RIDE;
        s_busy = false;
    }
}

